begin;
do $$
declare mapped_count int; distinct_count int; existing_count int; updated_count int;
begin
  create temp table catalogue_mapping(product_code text primary key,name_zh text,name_en text,brand text,flavour text,size text,package_type text,barcode text,category text) on commit drop;
  insert into catalogue_mapping values
  ('HK-001','礦泉水',null,'Cool',null,'750ml',null,null,'飲品'),('HK-002','媽咪麵',null,null,null,null,null,null,'即食麵'),('HK-003','QQ糖',null,'旺仔','藍莓',null,null,null,'糖果'),('HK-004','QQ糖',null,'旺仔','蜜桃',null,null,null,'糖果'),('HK-005','QQ糖',null,'旺仔','葡萄',null,null,null,'糖果'),('HK-006','薯片',null,'卡樂B','燒烤','25g',null,null,'薯片／脆片'),('HK-007','薯片',null,'卡樂B','番茄','55g',null,null,'薯片／脆片'),('HK-008','薯片',null,'卡樂B','熱浪','25g',null,null,'薯片／脆片'),('HK-009','魷魚絲',null,'大發',null,'30g',null,null,'肉類零食'),('HK-010','紫菜',null,'小老闆','原味',null,'袋裝',null,'紫菜'),('HK-011','紫菜',null,'小老闆','原味',null,'片裝',null,'紫菜'),('HK-012','紫菜',null,'小老闆','辣味',null,'片裝',null,'紫菜'),('HK-013','特濃牛奶',null,'旺仔',null,'125ml',null,null,'乳製品'),('HK-014',null,null,'維他奶',null,'250ml',null,null,'飲品'),('HK-015','麥精',null,'維他',null,'250ml',null,null,'飲品'),('HK-016','蘋果綠茶',null,null,null,'250ml',null,null,'飲品'),('HK-017','清涼爽',null,null,null,'300ml',null,null,'飲品'),('HK-018','菊花烏龍茶',null,'地道',null,'250ml',null,null,'飲品'),('HK-019','解茶',null,'地道',null,'250ml',null,null,'飲品'),('HK-020','茉莉綠茶',null,'地道',null,'250ml',null,null,'飲品'),('HK-021','檸檬茶',null,null,null,'250ml',null,null,'飲品'),('HK-022','白提子汁',null,'Qoo',null,null,null,null,'飲品'),('HK-023','荔枝玉露',null,null,null,null,'罐裝',null,'飲品'),('HK-024','抽紙',null,'維達','綠茶香',null,null,null,'紙品／日用品'),('HK-025','抽紙',null,'維達','爽身粉香',null,null,null,'紙品／日用品'),('HK-026','啫喱',null,null,'雜果',null,null,null,'啫喱'),('HK-027','小小酥',null,'旺旺','香蔥雞',null,null,null,'餅乾'),('HK-028','小小酥',null,'旺旺','原味',null,null,null,'餅乾'),('HK-029','美味棒',null,null,'忌廉湯',null,null,null,'餅乾'),('HK-030','奶片',null,null,null,null,null,null,'乳製品'),('HK-031','可樂橡皮糖',null,null,null,null,null,null,'糖果'),('HK-032','動物餅',null,null,null,null,'袋裝',null,'餅乾'),('HK-033','魚仔餅',null,null,'紫菜',null,null,null,'餅乾'),('HK-034','魚仔餅',null,null,'燒雞',null,null,null,'餅乾'),('HK-035','熊仔餅',null,null,'朱古力',null,null,null,'餅乾'),('HK-036','熊仔餅',null,null,'士多啤梨',null,null,null,'餅乾'),('HK-037','小饅頭',null,'旺仔',null,null,null,null,'餅乾'),('HK-038','黑白配',null,null,null,null,null,null,'餅乾'),('HK-039','仙貝',null,'旺旺',null,null,null,null,'餅乾'),('HK-040','燒餅',null,'旺旺',null,null,null,null,'餅乾'),('HK-041','百力滋',null,null,'抹茶',null,null,null,'餅乾'),('HK-042','百力滋',null,null,'番茄',null,null,null,'餅乾'),('HK-043','百力滋',null,null,'朱古力曲奇',null,null,null,'餅乾'),('HK-044','鵪鶉蛋',null,null,'鹽焗',null,null,null,'肉類零食'),('HK-045','鵪鶉蛋',null,null,'香辣',null,null,null,'肉類零食'),('HK-046','魷魚絲',null,null,'勁辣',null,null,null,'肉類零食'),('HK-047','腸仔',null,null,null,null,null,null,'肉類零食'),('HK-048','一口芝士條',null,null,null,null,null,null,'乳製品'),('HK-049','蒜香青豆',null,null,null,null,null,null,'堅果／豆類'),('HK-050','脆皮花生',null,null,null,null,null,null,'堅果／豆類'),('HK-051','醬油',null,'牛角',null,null,null,null,'調味／食品配料'),('HK-052','飯素',null,'牛角',null,null,null,null,'調味／食品配料'),('HK-053','甜筒蛋糕',null,null,null,null,null,null,'餅乾'),('HK-054','薯片',null,'卡樂B','雜菜',null,'掛裝',null,'薯片／脆片'),('HK-055','辛拉麵',null,null,null,null,null,null,'即食麵'),('HK-056','炒麵王',null,null,'香辣',null,null,null,'即食麵'),('HK-057','戒指糖',null,null,'雜',null,null,null,'糖果');
  select count(*),count(distinct lower(product_code)) into mapped_count,distinct_count from catalogue_mapping;
  if mapped_count<>57 or distinct_count<>57 then raise exception 'mapping cardinality'; end if;
  if exists((select product_code from catalogue_mapping) except (select format('HK-%s',lpad(n::text,3,'0')) from generate_series(1,57)n)) or exists((select format('HK-%s',lpad(n::text,3,'0')) from generate_series(1,57)n) except (select product_code from catalogue_mapping)) then raise exception 'mapping code set'; end if;
  select count(*) into existing_count
  from public.products p
  join catalogue_mapping m on lower(p.product_code)=lower(m.product_code);
  if existing_count=0 then
    raise notice 'No HK catalogue exists; skipping structured catalogue backfill';
    return;
  end if;
  if existing_count<>57 then raise exception 'Expected all 57 HK catalogue products, found %',existing_count; end if;
  update public.products p set name_zh=m.name_zh,name_en=m.name_en,brand=m.brand,flavour=m.flavour,size=m.size,package_type=m.package_type,barcode=m.barcode,category=m.category from catalogue_mapping m where lower(p.product_code)=lower(m.product_code);
  get diagnostics updated_count=row_count; if updated_count<>57 then raise exception 'updated %',updated_count; end if;
  if exists(select 1 from public.products p join catalogue_mapping m on lower(p.product_code)=lower(m.product_code) where p.name_zh is distinct from m.name_zh or p.name_en is distinct from m.name_en or p.brand is distinct from m.brand or p.flavour is distinct from m.flavour or p.size is distinct from m.size or p.package_type is distinct from m.package_type or p.barcode is distinct from m.barcode or p.category is distinct from m.category) then raise exception 'post assertion'; end if;
end $$;
commit;
